// Raw-socket path checks for server.mjs (not shipped). Usage: node raw.mjs <repoDir>
import { spawn } from 'node:child_process';
import net from 'node:net';
import { join } from 'node:path';

const child = spawn(process.execPath, [join(process.argv[2], 'server.mjs')], {
  env: { ...process.env, PORT: '0', DATA_FILE: '/tmp/bk-smoke/none/x.json' },
});
child.stdout.once('data', async (d) => {
  const port = Number(/:(\d+)/.exec(String(d))[1]);
  for (const t of ['/api/./rooms', '/api/rooms/', '/api/bookings/%31', 'http://x/api/rooms']) {
    await new Promise((res) => {
      const s = net.connect(port, '127.0.0.1', () => s.end(`GET ${t} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n`));
      let o = '';
      s.on('data', (x) => { o += x; });
      s.on('close', () => { console.log(t, o.split('\r\n')[0], o.slice(o.indexOf('\r\n\r\n') + 4)); res(); });
    });
  }
  child.kill();
});

